<?php
$connection = db();
$status = (string) ($_GET['status'] ?? 'all');
$q = trim((string) ($_GET['q'] ?? ''));
$allowed = ['all', 'new', 'confirmed', 'processing', 'ready', 'completed', 'cancelled'];
if (!in_array($status, $allowed, true)) $status = 'all';
$sql = "SELECT o.*, p.id payment_id, p.amount payment_amount, p.currency payment_currency, p.exchange_rate, p.reference_number, p.proof_path, GROUP_CONCAT(CONCAT(oi.quantity, ' x ', oi.product_name) ORDER BY oi.id SEPARATOR ', ') items FROM orders o LEFT JOIN payments p ON p.order_id=o.id LEFT JOIN order_items oi ON oi.order_id=o.id";
$where = []; $types = ''; $params = [];
if ($status !== 'all') { $where[] = 'o.status=?'; $types .= 's'; $params[] = $status; }
if ($q !== '') { $where[] = '(o.order_number LIKE ? OR o.customer_name LIKE ? OR o.phone LIKE ?)'; $types .= 'sss'; $term = '%' . $q . '%'; array_push($params, $term, $term, $term); }
if ($where) $sql .= ' WHERE ' . implode(' AND ', $where);
$sql .= ' GROUP BY o.id ORDER BY o.created_at DESC';
$statement = $connection->prepare($sql);
if ($params) { $references = []; foreach ($params as $key => $value) $references[$key] = &$params[$key]; $statement->bind_param($types, ...$references); }
$statement->execute(); $orders = $statement->get_result()->fetch_all(MYSQLI_ASSOC);
?>
