8px;color:#0e789f;font-size:11px;font-weight:800}.actions{display:flex;gap:10px;flex-wrap:wrap;padding:17px 24px;background:#fbfdfb;border-top:1px solid #e8efe9}.actions form{display:flex;gap:6px}.actions .button{height:38px}.empty{padding:45px;text-align:center;border:1px dashed #c7d7ca;border-radius:16px;color:var(--muted)}@media(max-width:1100px){.layout{grid-template-columns:1fr}.side{min-height:0;padding:18px;flex-direction:row;align-items:center;gap:8px;flex-wrap:wrap}.nav-label,.side-foot{display:none}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.main{padding:34px 24px}.order-body{grid-template-columns:1fr 1fr}}@media(max-width:650px){.main{padding:25px 14px}.head{display:block}.head h1{font-size:36px}.count{display:inline-block;margin-top:18px}.filters input{width:min(100%,270px)}.order-top,.order-body{display:block}.amount{text-align:left;margin-top:16px}.block{margin-top:10px}.actions form{width:100%}.actions select{flex:1}.actions .button{flex:1}.csv,.filters .button{width:100%}}
</style></head><body><div class="layout"><aside class="side"><a class="brand" href="index.php"><img src="../assets/images/sammy-tech-logo.jpeg" alt="Sammy Tech logo"><span><b>Sammy Tech</b><small>STAFF WORKSPACE</small></span></a><p class="nav-label">Operations</p><nav class="nav"><a href="index.php">Overview</a><a class="active" href="orders.php">Orders and payments</a><a href="catalog.php">Products</a><a href="installations.php">Installations</a><a href="reports.php">Reports</a><a href="backup.php">Backups</a></nav><div class="side-foot"><b>Customer view</b><a href="../index.php" target="_blank">Open storefront -&gt;</a></div></aside><main class="main"><header class="head"><div><p class="eyebrow">ORDER OPERATIONS</p><h1>Orders and payments.</h1><p>Review customer requests, payment details, and fulfilment status in one place.</p></div><span class="count"><?= count($orders) ?> order<?= count($orders) === 1 ? '' : 's' ?> shown</span></header><form class="filters" method="get"><label>FIND ORDER OR CUSTOMER<input name="q" value="<?= e($q) ?>" placeholder="Order number, name, phone"></label><label>ORDER STATUS<select name="status"><?php foreach($allowed as $option): ?><option value="<?= e($option) ?>" <?= $status === $option ? 'selected' : '' ?>><?= e(ucfirst($option)) ?></option><?php endforeach; ?></select></label><button class="button">Filter orders</button><a class="csv" href="export_orders.php">Download CSV</a></form><p class="results">Showing <?= count($orders) ?> matching order<?= count($orders) === 1 ? '' : 's' ?>.</p><?php if (!$orders): ?><div class="empty">No orders match this filter.</div><?php endif; ?><?php foreach($orders as $order): ?><article class="order"><header class="order-top"><div><div class="order-id"><h2><?= e($order['order_number']) ?></h2><span class="badge <?= e($order['status']) ?>"><?= e($order['status']) ?></span></div><p class="order-time"><?= e(date('d M Y, H:i', strtotime($order['created_at']))) ?> · <?= e(ucfirst($order['delivery_method'])) ?><?= $order['delivery_area'] ? ' · '.e($order['delivery_area']) : '' ?></p></div><div class="amount"><strong><?= money((float)$order['total_amount']) ?></strong><span>Payment: <?= e(ucfirst($order['payment_status'])) ?></span></div></header><section class="order-body"><div class="block"><span>CUSTOMER</span><b><?= e($order['customer_name']) ?></b><p><?= e($order['phone']) ?><?= $order['email'] ? '<br>'.e($order['email']) : '' ?></p></div><div class="block"><span>ORDER ITEMS</span><b><?= e($order['items'] ?: 'No items recorded') ?></b><p><?= $order['delivery_address'] ? 'Address: '.e($order['delivery_address']) : ($order['notes'] ? 'Note: '.e($order['notes']) : 'No additional delivery notes.') ?></p></div><div class="block blue"><span>CUSTOMER PAYMENT CHOICE</span><b><?= e(ucwords(str_replace('_',' ',$order['payment_method']))) ?> · <?= e((string)($order['payment_currency'] ?: 'USD')) ?> <?= e(number_format((float)($order['payment_amount'] ?? $order['total_amount']), 2)) ?></b><p><?= $order['reference_number'] ? 'Reference: '.e($order['reference_number']) : 'No reference number supplied.' ?></p><?php if($order['proof_path'] && $order['payment_id']): ?><a class="proof" href="payment_proof.php?payment_id=<?= e((string)$order['payment_id']) ?>" target="_blank">View payment proof -&gt;</a><?php endif; ?></div></section><footer class="actions"><form action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="order_id" value="<?= e((string)$order['id']) ?>"><input type="hidden" name="action" value="status"><select name="status"><?php foreach(array_slice($allowed,1) as $option): ?><option value="<?= e($option) ?>" <?= $order['status'] === $option ? 'selected' : '' ?>><?= e(ucfirst($option)) ?></option><?php endforeach; ?></select><button class="button">Save order</button></form><form action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="order_id" value="<?= e((string)$order['id']) ?>"><input type="hidden" name="action" value="payment"><select name="payment_status"><?php foreach(['pending','paid','failed','refunded'] as $option): ?><option value="<?= e($option) ?>" <?= $order['payment_status'] === $option ? 'selected' : '' ?>><?= e(ucfirst($option)) ?></option><?php endforeach; ?></select><button class="button">Save payment</button></form></footer></article><?php endforeach; ?></main></div></body></html>
